let original=null,displayed=null,result=null,targets=[],picks=[],region=null,tool='pick',mode='original',sourceName='森林来信',sourceSize=[0,0],revision=0,analysisSeq=0,renderSeq=0,busy=0,toastTimer,drag=null,saved=[];
