function setBusy(on){busy=Math.max(0,busy+(on?1:-1));$('#loading').hidden=!busy;$('#extract-btn').disabled=busy>0||!original;$$('[data-mode], .target input, #color-count, #clear-region, #pick-tool, #region-tool, #export-image, #export-palette, #save-palette, #reset-colors').forEach(el=>el.disabled=busy>0);}
let worker=null,jobId=0;const pending=new Map();
const fallback=m=>new Promise((resolve,reject)=>setTimeout(()=>{try{resolve(m.type==='analyze'?ColorLab.analyze(m.pixels,m.width,m.height,m.k,m.region):ColorLab.recolor(m.pixels,m.palette,m.targets,m.mode));}catch(e){reject(e);}},20));
