function emptyResults(){result=null;targets=[];for(const s of ['#color-list','#palette-strip','#target-colors','#histogram'])$(s).replaceChildren();$('#result-scope').textContent='等待提取';$('#stat-light').textContent=$('#stat-sat').textContent='—';$('#analysis-note').textContent='正在分析这张参考图…';}
async function loadImage(url,name,isLocal=false){const rev=++revision;analysisSeq++;renderSeq++;setBusy(true);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('图片无法解码，请尝试其他 JPG、PNG 或 WebP 图片。'));i.src=url;});if(rev!==revision)return;if(img.naturalWidth*img.naturalHeight>64e6)throw Error('图片超过 6400 万像素，请先缩小后再导入。');const scale=Math.min(1,1000/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));canvas.width=overlay.width=w;canvas.height=overlay.height=h;$('#canvas-wrap').style.maxWidth=Math.round(w/h*520)+'px';ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);original=ctx.getImageData(0,0,w,h);displayed=original;region=null;picks=[];mode='original';sourceName=name;sourceSize=[img.naturalWidth,img.naturalHeight];emptyResults();renderPicks();drawRegion();updateModeButtons();$('#dimensions').textContent=w+' × '+h;$('#image-label').textContent=name;$('#file-info').textContent=`${name} · 原图 ${sourceSize.join(' × ')} · 分析 ${w} × ${h}`;updateScope();await extract();}catch(e){if(rev===revision)toast(e.message);}finally{if(isLocal)URL.revokeObjectURL(url);setBusy(false);}}
