function updateScope(changed=false){$('#scope-info').textContent=(region?'已框选区域':'整张图片')+(changed?' · 参数已变更，点击重新提取':' · 点击下方按钮提取');}
async function extract(){if(!original)return;const seq=++analysisSeq,rev=revision;renderSeq++;setBusy(true);try{const r=await job({type:'analyze',pixels:original.data,width:original.width,height:original.height,k:Number($('#color-count').value),region});if(seq!==analysisSeq||rev!==revision)return;result=r;targets=r.colors.map(c=>c.hex);mode='original';updateModeButtons();renderResult();renderTargets();ctx.putImageData(original,0,0);displayed=original;$('#scope-info').textContent=`${region?'区域':'整图'}提取完成 · ${r.sampleCount.toLocaleString()} 个采样`;toast(`已收集 ${r.colors.length} 种主色。点击 HEX 可以复制，下方色块可以试着换色。`);}catch(e){if(rev===revision)toast(e.message);}finally{setBusy(false);}}
