function renderResult(){const r=result;$('#palette-strip').replaceChildren(...r.colors.map(colorSpan));$('#result-scope').textContent=(region?'区域配色':'整图配色')+' · '+r.colors.length+' 色';$('#color-list').replaceChildren(...r.colors.map(c=>{const b=document.createElement('button');b.className='color-row';b.title='复制 '+c.hex;b.setAttribute('aria-label','复制颜色 '+c.hex);const dot=document.createElement('span');dot.className='color-dot';dot.style.background=c.hex;const text=document.createElement('span'),h=document.createElement('span'),rgb=document.createElement('span'),weight=document.createElement('span');h.className='color-hex';h.textContent=c.hex;rgb.className='color-rgb';rgb.textContent='RGB '+c.rgb.join(' · ');weight.className='color-weight';weight.textContent=(c.weight*100).toFixed(1)+'%';text.append(h,rgb);b.append(dot,text,weight);b.onclick=()=>copy(c.hex);return b;}));$('#stat-light').textContent=r.meanLightness.toFixed(0)+' / 100';$('#stat-sat').textContent=Math.round(r.saturation*100)+'%';$('#light-meter').style.left=r.meanLightness+'%';$('#sat-meter').style.left=(r.saturation*100)+'%';const max=Math.max(...r.histogram);$('#histogram').replaceChildren(...r.histogram.map(v=>{const i=document.createElement('i');i.style.height=v/max*100+'%';return i;}));$('#analysis-note').textContent=`${r.meanLightness>65?'整体明亮轻盈':r.meanLightness<40?'整体偏暗沉静':'明暗比较均衡'}，${r.saturation<.3?'色彩柔和克制':r.saturation>.6?'色彩鲜明活泼':'色彩温和丰富'}。L* 标准差 ${r.lightnessStd.toFixed(1)}，帮助观察明暗分散程度。`;}
function renderTargets(){$('#target-colors').replaceChildren(...targets.map((h,i)=>{const label=document.createElement('div');label.className='target';const input=document.createElement('input'),hexInput=document.createElement('input');input.type='color';input.value=h;input.disabled=busy>0;input.setAttribute('aria-label','替换主色 '+(i+1)+' '+h);hexInput.type='text';hexInput.value=h;hexInput.maxLength=7;hexInput.spellcheck=false;hexInput.disabled=busy>0;hexInput.setAttribute('aria-label','替换色值 '+(i+1));function apply(value){if(!ColorLab.unhex(value)){hexInput.value=targets[i];toast('请输入完整的 HEX 色值，例如 #93A87B。');return;}targets[i]=value.toUpperCase();input.value=hexInput.value=targets[i];mode='recolor';updateModeButtons();renderPreview();}input.onchange=()=>apply(input.value);hexInput.onchange=()=>apply(hexInput.value);hexInput.onblur=()=>{if(hexInput.value.toUpperCase()!==targets[i])apply(hexInput.value);};hexInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();apply(hexInput.value);}};label.append(input,hexInput);return label;}));}
