function point(e){const b=overlay.getBoundingClientRect();return [Math.max(0,Math.min(overlay.width-1,(e.clientX-b.left)/b.width*overlay.width)),Math.max(0,Math.min(overlay.height-1,(e.clientY-b.top)/b.height*overlay.height))];}
