async function renderPreview(){if(!original)return;const seq=++renderSeq,rev=revision;if(mode==='original'){ctx.putImageData(original,0,0);displayed=original;return;}if(!result){toast('请先提取主色，再做配色实验。');mode='original';updateModeButtons();return;}setBusy(true);try{const p=await job({type:'render',pixels:original.data,palette:result.colors,targets:targets.slice(),mode});if(seq!==renderSeq||rev!==revision)return;displayed=new ImageData(new Uint8ClampedArray(p),original.width,original.height);ctx.putImageData(displayed,0,0);}catch(e){toast('预览失败：'+e.message);}finally{setBusy(false);}}
