const safeName=s=>s.replace(/[\\/:*?"<>|\u0000-\u001f]/g,'_').slice(0,70)||'palette';
function imageDownload(c,name){c.toBlob(blob=>{if(blob){download(blob,name+'.png');toast('已生成 PNG，浏览器将保存到下载文件夹。');}else toast('导出失败，请换一个浏览器重试。');},'image/png');}
