function paletteRecord(){return {format:'palette-atelier',version:1,name:sourceName+' · 配色',colors:result.colors.map(c=>({hex:c.hex,rgb:c.rgb,weight:c.weight})),analysis:{algorithm:result.algorithm,sampleCount:result.sampleCount,region:result.region,meanLightness:result.meanLightness,saturation:result.saturation,lightnessStd:result.lightnessStd},source:{name:sourceName,originalSize:sourceSize,workingSize:[original.width,original.height]}};}
function exportPalette(r,format){const name=safeName(r.name);if(format==='json'){download(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),name+'.json');toast('色卡 JSON 已生成。');}else if(format==='gpl'){const text=['GIMP Palette','Name: '+r.name.replace(/[\r\n]/g,' '),'Columns: '+r.colors.length,'# Exported by Palette Atelier',...r.colors.map(c=>ColorLab.unhex(c.hex).map(v=>String(v).padStart(3)).join(' ')+'\t'+c.hex)].join('\n');download(new Blob([text],{type:'text/plain'}),name+'.gpl');toast('GPL 色卡已生成，可导入 GIMP 或 Krita。');}else{const c=document.createElement('canvas');c.width=1200;c.height=740;const x=c.getContext('2d');x.fillStyle='#f7f3e8';x.fillRect(0,0,1200,740);x.fillStyle='#647655';x.font='32px Georgia';x.fillText('Palette Atelier',64,83);x.font='18px sans-serif';x.fillStyle='#8a947d';x.fillText(r.name.slice(0,45),64,126);const total=r.colors.reduce((s,c)=>s+c.weight,0);let pos=64;r.colors.forEach(col=>{const w=1072*col.weight/total;x.fillStyle=col.hex;x.fillRect(pos,170,w,240);pos+=w;});const cell=1072/r.colors.length;r.colors.forEach((col,i)=>{const left=64+i*cell;x.fillStyle=col.hex;x.fillRect(left,458,cell-13,70);x.fillStyle='#667254';x.font='16px monospace';x.fillText(col.hex,left,558);x.fillStyle='#989c88';x.font='14px sans-serif';x.fillText((col.weight/total*100).toFixed(1)+'%',left,585);});x.fillStyle='#a1a68d';x.font='14px sans-serif';x.fillText('A LITTLE COLOR, A LITTLE WONDER   ·   sRGB / sampled palette',64,685);imageDownload(c,name);}}
$('#export-palette').onclick=()=>{if(result)exportPalette(paletteRecord(),$('#export-format').value);else toast('先提取一组颜色吧。');};
function persist(){try{localStorage.setItem('palette-atelier.v1',JSON.stringify(saved));return true;}catch(e){toast('浏览器未允许保存收藏，你仍可导出 JSON 备份。');return false;}}
function updateSavedCount(){$('#saved-count').textContent=saved.length;}
$('#save-palette').onclick=()=>{if(!result){toast('先提取一组颜色吧。');return;}if(saved.length>=50){toast('收藏已满 50 组，请先导出备份，再删除不需要的色卡。');return;}saved.unshift({...paletteRecord(),id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)});updateSavedCount();if(persist())toast('已收藏这组颜色，在「色卡收藏」里可以找到。');};
function renderCollection(){updateSavedCount();const box=$('#collection-list');box.replaceChildren();if(!saved.length){const p=document.createElement('p');p.className='muted';p.textContent='这里还空着。回到工作台，收藏第一组喜欢的颜色吧。';box.append(p);}for(const r of saved){const card=document.createElement('article');card.className='saved-card';const head=document.createElement('div');head.className='saved-head';const input=document.createElement('input');input.className='saved-name';input.value=r.name;input.maxLength=100;input.setAttribute('aria-label','修改色卡名称');input.onchange=()=>{r.name=input.value.trim()||'未命名色卡';persist();};head.append(input);for(const [text,fn]of [['PNG',()=>exportPalette(r,'png')],['JSON',()=>exportPalette(r,'json')],['删除',()=>{saved=saved.filter(x=>x.id!==r.id);persist();renderCollection();}]]){const b=document.createElement('button');b.className='text-btn';b.textContent=text;b.onclick=fn;head.append(b);}const strip=document.createElement('div');strip.className='palette-strip';strip.append(...r.colors.map(colorSpan));const vals=document.createElement('div');vals.className='saved-values';vals.textContent=r.colors.map(c=>c.hex).join(' ');card.append(head,strip,vals);box.append(card);}}
$('#palette-input').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>1024*1024)throw Error('色卡 JSON 请小于 1 MB。');const r=JSON.parse(await f.text()),v={...r,name:String(r.name||'导入的色卡').slice(0,100),id:Date.now().toString(36)+'-import'};if(r.format!=='palette-atelier'||r.version!==1||!validSaved(v))throw Error('不是有效的 Palette Atelier 色卡 JSON。');if(saved.length>=50)throw Error('收藏已满，请先删掉不需要的色卡。');v.colors=v.colors.map(c=>({hex:c.hex.toUpperCase(),rgb:ColorLab.unhex(c.hex),weight:c.weight}));saved.unshift(v);persist();renderCollection();toast('已导入色卡。');}catch(err){toast(err.message);}};
function openGuide(){$('#guide-dialog').showModal();}$('#guide-nav').onclick=openGuide;$('#footer-guide').onclick=openGuide;$('#collection-nav').onclick=()=>{renderCollection();$('#collection-dialog').showModal();};$('#workspace-nav').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('.brand').onclick=e=>{e.preventDefault();window.scrollTo({top:0,behavior:'smooth'});};$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}});
